{
  "technical_and_design_decisions": [
    "Implementation language: Go (consistent with Hyperledger Fabric codebase)",
    "New helper functions will be added to the existing channel configuration API packages (likely `configtx` or `config`)",
    "Functions will follow existing patterns for config mutation: accept a configtx.ConfigUpdateEnvelope or similar mutable config object, modify it, and return it for chaining",
    "Policy addition/removal will manipulate the `Policies` map in the relevant config groups (Application, Orderer, Consortium)",
    "MSP configuration retrieval will parse the `MSP` field from the organization's config",
    "Certificate revocation will verify the certificate against the MSP's root/intermediate CAs before adding to the `RevocationList` in `FabricMSPConfig`",
    "Unit tests will use table-driven tests and mock config structures; example tests will be updated in existing integration test files",
    "Error handling will follow Go conventions (return error as last return value)"
  ],
  "assumptions": [
    "Developer has working knowledge of Hyperledger Fabric channel configuration internals",
    "Existing codebase has adequate test infrastructure; no new test framework setup required",
    "Example tests refer to existing end-to-end test files that demonstrate API usage (e.g., `configtx/testutil` or similar)",
    "All functions operate on in-memory config structures; no persistence or network calls needed",
    "No database migrations or schema changes required",
    "Effort estimates assume a single developer working full-time with no context-switching overhead",
    "Code review and CI/CD pipeline execution time are not included in development effort estimates"
  ],
  "activities": [
    {
      "activity_id": "U1-Impl",
      "activity_name": "U1: Implement retrieve organization configuration helper",
      "activity_description": "Design and implement function to retrieve application, orderer, or consortium org configuration from a config transaction, returning config.Organization. Includes parsing logic for different group types.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U1-UnitTest",
      "activity_name": "U1: Unit tests for retrieve organization configuration",
      "activity_description": "Write table-driven unit tests covering retrieval of each org type (application, orderer, consortium) and error cases (org not found, malformed config).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U1-ExampleTest",
      "activity_name": "U1: Update example tests for retrieve organization configuration",
      "activity_description": "Add demonstration of the new helper in existing example/integration test files showing retrieval, modification, and update flow.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U2-Impl",
      "activity_name": "U2: Implement application org/group policy add/remove functions",
      "activity_description": "Design and implement functions to add and remove policies from application org and application group configurations. Handle policy map manipulation and validation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U2-UnitTest",
      "activity_name": "U2: Unit tests for application policy add/remove",
      "activity_description": "Write unit tests for adding/removing policies at both org and group levels, including edge cases (duplicate policy, non-existent policy, nil map).",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "U2-ExampleTest",
      "activity_name": "U2: Update example tests for application policy add/remove",
      "activity_description": "Extend example tests to demonstrate policy addition and removal on application org and group, showing chaining with other config updates.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U3-Impl",
      "activity_name": "U3: Implement orderer org/group policy add/remove functions",
      "activity_description": "Design and implement functions to add and remove policies from orderer org and orderer group configurations. Similar to U2 but for orderer context.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U3-UnitTest",
      "activity_name": "U3: Unit tests for orderer policy add/remove",
      "activity_description": "Write unit tests for orderer org and group policy manipulation, mirroring U2 test coverage.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "U3-ExampleTest",
      "activity_name": "U3: Update example tests for orderer policy add/remove",
      "activity_description": "Update example tests to demonstrate orderer policy add/remove usage.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U4-Impl",
      "activity_name": "U4: Implement consortium org/group policy add/remove functions",
      "activity_description": "Design and implement functions to add and remove policies from consortium org, consortiums group, and consortium group configurations. Handle three-level hierarchy.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U4-UnitTest",
      "activity_name": "U4: Unit tests for consortium policy add/remove",
      "activity_description": "Write unit tests covering all three consortium levels (org, consortiums group, consortium group) for policy add/remove.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "U4-ExampleTest",
      "activity_name": "U4: Update example tests for consortium policy add/remove",
      "activity_description": "Update example tests to demonstrate consortium policy manipulation at all levels.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U5-Impl",
      "activity_name": "U5: Implement add orderer org definition function",
      "activity_description": "Design and implement function to add a new orderer organization definition to a channel configuration, returning a mutable config transaction for further updates.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U5-UnitTest",
      "activity_name": "U5: Unit tests for add orderer org definition",
      "activity_description": "Write unit tests verifying the generated config transaction contains the new orderer org with correct structure, MSP, and default policies.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U5-ExampleTest",
      "activity_name": "U5: Update example tests for add orderer org definition",
      "activity_description": "Add example test demonstrating creation of a new orderer org and chaining further modifications.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U6-Impl",
      "activity_name": "U6: Implement add application org definition function",
      "activity_description": "Design and implement function to add a new application organization definition to a channel configuration, returning a mutable config transaction.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U6-UnitTest",
      "activity_name": "U6: Unit tests for add application org definition",
      "activity_description": "Write unit tests verifying the generated config transaction contains the new application org with correct structure, MSP, and default policies.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U6-ExampleTest",
      "activity_name": "U6: Update example tests for add application org definition",
      "activity_description": "Add example test demonstrating creation of a new application org and chaining further modifications.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U7-Impl",
      "activity_name": "U7: Implement retrieve MSP configuration helper",
      "activity_description": "Design and implement function to retrieve MSP configuration for a specific organization from a config transaction, returning the MSP config structure for reuse.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U7-UnitTest",
      "activity_name": "U7: Unit tests for retrieve MSP configuration",
      "activity_description": "Write unit tests covering MSP config retrieval for different org types, including error cases (org not found, missing MSP config).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "U7-ExampleTest",
      "activity_name": "U7: Update example tests for retrieve MSP configuration",
      "activity_description": "Update example tests to demonstrate retrieving MSP config and reusing CA certs or other fields.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "U8-Impl",
      "activity_name": "U8: Implement certificate revocation function",
      "activity_description": "Design and implement function to revoke a certificate by verifying it was issued by the MSP's CA chain and adding it to the FabricMSPConfig revocation list. Return error for certificates not issued by the MSP.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "U8-UnitTest",
      "activity_name": "U8: Unit tests for certificate revocation",
      "activity_description": "Write unit tests covering successful revocation, verification failure (cert not issued by MSP), and edge cases (expired cert, already revoked, malformed cert).",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "U8-ExampleTest",
      "activity_name": "U8: Update example tests for certificate revocation",
      "activity_description": "Add example test demonstrating certificate revocation flow with both success and error cases.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "Common-Setup",
      "activity_name": "Common test utilities and shared setup",
      "activity_description": "Create or update shared test utilities (mock config transactions, helper functions for building test configs) used across all user stories.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 35
  }
}

